const labelToKey = {"Body ache":"body_ache","Chest tightness":"chest_tightness","Chills":"chills","Constipation":"constipation","Cough":"cough","Diarrhea":"diarrhea","Difficulty breathing":"difficulty_breathing","Dry cough":"dry_cough","Fatigue":"fatigue","Fever":"fever","Headache":"headache","High fever":"high_fever","Itchy rash":"itchy_rash","Joint pain":"joint_pain","Loss of appetite":"loss_of_appetite","Loss of taste or smell":"loss_of_taste_smell","Mild cough":"mild_cough","Mild fever":"mild_fever","Mild headache":"mild_headache","Muscle pain":"muscle_pain","Nasal congestion":"nasal_congestion","Nausea":"nausea","Pain behind eyes":"pain_behind_eyes","Prolonged fever":"prolonged_fever","Runny nose":"runny_nose","Sensitivity to light":"sensitivity_to_light","Sensitivity to sound":"sensitivity_to_sound","Severe headache":"severe_headache","Skin rash":"skin_rash","Sneezing":"sneezing","Sore throat":"sore_throat","Stomach cramps":"stomach_cramps","Stomach pain":"stomach_pain","Sweating":"sweating","Visual disturbance":"visual_disturbance","Vomiting":"vomiting","Weakness":"weakness","Wheezing":"wheezing"};
const raw = $json.symptoms;
let labels = [];
if (Array.isArray(raw)) { labels = raw; }
else if (typeof raw === "string" && raw.length) { labels = raw.split(",").map(function(s){ return s.trim(); }); }
const symptoms = labels.map(function(l){ return labelToKey[l] || l.toLowerCase().replace(/\s+/g,"_"); });
return [{ json: { symptoms: symptoms, results: [] } }];

const symptoms = new Set($('Normalize Symptoms').item.json.symptoms);
const rule = {"disease":"Common Cold","symptoms":{"runny_nose":0.9,"sneezing":0.85,"sore_throat":0.6,"mild_cough":0.6,"nasal_congestion":0.8,"mild_headache":0.3},"advice":"Usually self-limiting. Rest, fluids, and OTC cold relief are typically enough."};
const matched = {}; const missing = {};
for (const s in rule.symptoms) { if (symptoms.has(s)) { matched[s] = rule.symptoms[s]; } else { missing[s] = rule.symptoms[s]; } }
const matchedCount = Object.keys(matched).length;
const matchedWeight = Object.values(matched).reduce(function(a,b){ return a+b; }, 0);
const totalWeight = Object.values(rule.symptoms).reduce(function(a,b){ return a+b; }, 0);
const confidence = totalWeight > 0 ? matchedWeight/totalWeight : 0;
const fires = matchedCount >= 2 && confidence >= 0.30;
const previousResults = $json.results || [];
const thisResult = { disease: rule.disease, confidence: confidence, matchedCount: matchedCount, matched: matched, missing: missing, advice: rule.advice, fires: fires };
return [{ json: { symptoms: Array.from(symptoms), results: previousResults.concat([thisResult]) } }];

