const ranked = $json.ranked;
const symptoms = $json.symptoms;
let text = "Reported symptoms: " + symptoms.join(", ") + "\n\n";
ranked.slice(0,5).forEach(function(r, i){
  const pct = Math.round(r.confidence*100);
  const label = r.confidence >= 0.7 ? "High likelihood" : (r.confidence >= 0.5 ? "Moderate likelihood" : "Low likelihood");
  text += (i+1) + ". " + r.disease + " - " + label + " (" + pct + "% match)\n";
  text += "   Matched: " + Object.keys(r.matched).join(", ") + "\n";
  text += "   Advice: " + r.advice + "\n\n";
});
text += "Not a diagnosis. Consult a physician for real symptoms.";
return [{ json: { displayText: text } }];
